#include "object/coin_explode.hpp"

#include "math/random.hpp"
#include "object/coin.hpp"
#include "supertux/sector.hpp"

#include <array>

CoinExplode::CoinExplode(const Vector& pos, bool count_stats, const std::string& sprite) :
  m_sprite(sprite),
  position(pos),
  m_count_stats(count_stats)
{
}

void
CoinExplode::update(float )
{
  float mag = 100.0f; // Magnitude at which coins are thrown.
  float rand = 30.0f; // Max variation to be subtracted from the magnitude.

  // Each coin in the explosion has a different velocity.
  static const std::array<Vector, 5> coin_velocities = {{
    { 2.5f, -4.5f }, { 2.f, -5.f },
    { 1.5f, -5.5f }, { 1.f, -6.f }, { 0.5f, -6.5f }
  }};

  for (const auto& vector : coin_velocities)
  {
    for (const float side : { 1.f, -1.f })
    {
      const Vector velocity = Vector(vector.x, vector.y * side) * (mag - gameRandom.randf(rand));
      Sector::get().add<HeavyCoin>(position, velocity, m_count_stats, m_sprite);
    }
  }

  remove_me();
}

void
CoinExplode::draw(DrawingContext &)
{
}
  if (!is_grabbed()) {

    if (get_bbox().get_top() > Sector::get().get_height()) {
      remove_me();
    }

    Rectf icebox = get_bbox().grown(-1.f);
    icebox.set_bottom(get_bbox().get_bottom() + 8.f);
    m_on_ice = !Sector::get().is_free_of_tiles(icebox, true, Tile::ICE);

    bool in_water = !Sector::get().is_free_of_tiles(get_bbox(), true, Tile::WATER);
    m_physic.set_gravity_modifier(in_water ? 0.2f : 1.f);

    Rectf trampolinebox = get_bbox().grown(-1.f);
    trampolinebox.set_bottom(get_bbox().get_bottom() + 8.f);

    for (auto& trampoline : Sector::get().get_objects_by_type<Trampoline>()) {
      if (trampolinebox.overlaps(trampoline.get_bbox()) && !trampoline.is_grabbed() &&
        (glm::length((get_bbox().get_middle() - trampoline.get_bbox().get_middle())) >= 10.f) &&
        is_portable()) {
        trampoline.bounce();
        m_physic.set_velocity_y(-500.f);
      }
    }

    const float sector_gravity = Sector::get().get_gravity();

    Rectf playerbox = get_bbox().grown(-2.f);
    if (sector_gravity > 0.f) {
      playerbox.set_bottom(get_bbox().get_bottom() + 7.f);
    }
    else {
      playerbox.set_top(get_bbox().get_top() - 7.f);
    }
    for (auto& player : Sector::get().get_objects_by_type<Player>()) {
      if (playerbox.overlaps(player.get_bbox()) && is_portable() &&
      ((sector_gravity > 0.f && m_physic.get_velocity_y() > 0.f) || (sector_gravity < 0.f && m_physic.get_velocity_y() < 0.f))) {
        m_physic.set_velocity_y(sector_gravity > 0.f ? -250.f : 250.f);
      }
    }

    m_col.set_movement(m_physic.get_movement(dt_sec) *
      Vector(in_water ? 0.4f : 1.f, in_water ? 0.6f : 1.f));

    if (m_last_sector_gravity != sector_gravity)
    {
      if ((sector_gravity < 0.0f && m_last_sector_gravity >= 0.0f) ||
          (sector_gravity >= 0.0f && m_last_sector_gravity < 0.0f))
      {
        // gravity has changed direction, reset flags
        m_on_ground = false;

